{
  "name": "@luxass/opencode-personal",
  "version": "0.2.3",
  "description": "Personal OpenCode plugins collected in one package, tuned to a single workflow.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "personal"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/luxass/agent-extensions",
    "directory": "packages/opencode-personal"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "type": "module",
  "exports": {
    ".": "./src/index.ts",
    "./crow": "./src/crow/index.ts",
    "./dependency-policy": "./src/dependency-policy.ts",
    "./git-interceptor": "./src/git-interceptor.ts",
    "./package-manager-interceptor": "./src/package-manager-interceptor.ts",
    "./worker-configuration-guard": "./src/worker-configuration-guard.ts"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode/plugin": "2.1.1",
    "effect": "4.0.1"
  },
  "engines": {
    "node": ">=24"
  },
  "scripts": {
    "lint": "oxlint .",
    "lint:fix": "oxlint --fix .",
    "fmt": "oxfmt .",
    "fmt:check": "oxfmt --check .",
    "typecheck": "tsc -p tsconfig.json"
  }
}
